def transform(grid):
    h, w = len(grid), len(grid[0])
    background = max(range(10), key=lambda c: sum(v == c for row in grid for v in row))
    sep_rows = [r for r, row in enumerate(grid) if len(set(row)) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def spans(size, separators):
        result = []
        start = 0
        for p in separators:
            if start < p:
                result.append((start, p))
            start = p + 1
        if start < size:
            result.append((start, size))
        return result

    rows = spans(h, sep_rows)
    cols = spans(w, sep_cols)
    out = []
    for r0, r1 in rows:
        line = []
        for c0, c1 in cols:
            count = sum(
                grid[r][c] != background
                for r in range(r0, r1)
                for c in range(c0, c1)
            )
            line.append(1 if count > 1 else background)
        out.append(line)
    return out
